def min_covering_window(values, required):
    if not required:
        return [0, 0]

    required_counts = {}
    for x in required:
        required_counts[x] = required_counts.get(x, 0) + 1

    required_distinct = len(required_counts)
    window_counts = {}
    formed = 0
    left = 0
    best_len = float('inf')
    best_start = 0

    for right, val in enumerate(values):
        window_counts[val] = window_counts.get(val, 0) + 1

        if val in required_counts and window_counts[val] == required_counts[val]:
            formed += 1

        while left <= right and formed == required_distinct:
            val_left = values[left]

            if right - left + 1 < best_len:
                best_len = right - left + 1
                best_start = left

            window_counts[val_left] -= 1
            if val_left in required_counts and window_counts[val_left] < required_counts[val_left]:
                formed -= 1
            left += 1

    if best_len == float('inf'):
        return None

    return [best_start, best_start + best_len]
